style.css:
@-moz-document domain("roblox.com") {
/* Main Background and Containers */
    body, 
    .container-main, 
    .content, 
    .rbx-left-col,
    .section-content,
    .gandalf-settings-page .content {
        background-color: #FFF0F5 !important; /* Lavender Blush / Light Pastel Pink */
        color: #5D4037 !important; /* Soft brown text for contrast */
    }

    /* Top Header Navigation Bar */
    #header, 
    .rbx-header {
        background-color: #FFC0CB !important; /* Pastel Pink */
    }

    /* Left Sidebar Navigation */
    .rbx-left-col, 
    #navigation {
        background-color: #FFE4E1 !important; /* Misty Rose */
    }

    /* Category Cards and Boxes */
    .game-card-container, 
    .item-card-container, 
    .vngage-sub-container,
    .section-content {
        background-color: #FFFFFF !important;
        border: 2px solid #FFD1DC !important; /* Soft Pink Border */
        border-radius: 8px !important;
    }

    /* Buttons and Links */
    .btn-primary-md, 
    .btn-growth-md, 
    .buy-button, 
    .play-button {
        background-color: #FFB7C5 !important; /* Cherry Blossom Pink */
        color: #FFFFFF !important;
        border: none !important;
        border-radius: 20px !important;
        box-shadow: 0px 4px 6px rgba(255, 183, 197, 0.4) !important;
    }

    .btn-primary-md:hover, 
    .play-button:hover {
        background-color: #FFA6B6 !important; /* Darker pastel pink on hover */
    }

    /* Text Links */
    a, .text-link, .rbx-menu-item {
        color: #DB7093 !important; /* Pale Violet Red */
    }
    
    a:hover {
        color: #C71585 !important;
    }

    /* Search Bar and Inputs */
    .input-field, 
    #navbar-search-input {
        background-color: #FFFFFF !important;
        border: 1px solid #FFD1DC !important;
        color: #5D4037 !important;
    }
}
